        id: occurrence.id,
        title: `${session.mode} \xB7 ${occurrence.sourceId}@${task.revision} \xB7 content version ${session.version}${session.mission ? ` \xB7 ${session.mission.title}` : ""}`,
        prompt: "",
        topic: task.topicId,
